"""Row-limit boundary: independent completion-set counting vs driver images.

Family: words s0^5 s1^4 s2^4 s0 s1 s2 (length 16) for triples s in [16]^3.
All 3-suffixes are distinct so residuals stay distinct deep into the trie.
"""
import itertools, sys
sys.path.insert(0, '/workspace/tests')
from harness import *

NAMES = [chr(ord('a') + i).upper() for i in range(16)]
SVC = [{"name": n, "label": i + 1} for i, n in enumerate(NAMES)]
LIM = {"images": 16, "cells": 262144, "units": 1024, "contexts": 32768,
       "connections": 4096, "packets": 32768, "files": 8192}

def count_rows(wordset):
    words = set(tuple(w) for w in wordset)
    if not words:
        return 1
    children = [{}]
    terminal = [False]
    for w in words:
        node = 0
        for ch in w:
            nxt = children[node].get(ch)
            if nxt is None:
                nxt = len(children)
                children[node][ch] = nxt
                children.append({})
                terminal.append(False)
            node = nxt
        terminal[node] = True
    canon = [None] * len(children)

    def canon_of(node):
        if canon[node] is None:
            canon[node] = (terminal[node],
                           frozenset((ch, canon_of(c2)) for ch, c2 in children[node].items()))
        return canon[node]
    return len({canon_of(n) for n in range(len(children))})

def make_policy(wordset):
    return "".join(f"match({','.join(w)}) allow;" for w in sorted(wordset))

def rows_from_driver(wordset):
    r = run_cli(req([job(SVC, [{"op": "stage", "epoch": 1, "policy": make_policy(wordset)}], LIM)]))
    e = r["results"][0]["events"][0]
    return len(e['image']['rows']) if 'image' in e else e

def expect_rows(name, wordset):
    n = count_rows(wordset)
    got = rows_from_driver(wordset)
    if n > 8192:
        check(name + f" (rows {n} > 8192)", got, {"error": "rejected"})
    else:
        check(name + f" (rows {n})", got, n)

# small sanity
expect_rows("chain n=5", [("A",)*i + ("B",) for i in range(5)])

# main family
all3 = list(itertools.product(NAMES, repeat=3))

def family(n):
    words = []
    for s in all3[:n]:
        s0, s1, s2 = s
        w = (s0,)*5 + (s1,)*4 + (s2,)*4 + (s0, s1, s2)
        words.append(w)
    return words

expect_rows("full family", family(4096))
expect_rows("family 1024", family(1024))

# locate boundary rows 8192 / 8193
cache = {}
lo, hi = 1024, 4096
hits = {}
# rows monotone in n; binary search for 8192
while lo < hi:
    mid = (lo + hi) // 2
    cache[mid] = count_rows(family(mid))
    if cache[mid] < 8192:
        lo = mid + 1
    else:
        hi = mid
for n in range(max(1024, lo - 3), min(4096, lo + 4)):
    cache[n] = count_rows(family(n))
print("   rows near boundary:", {n: cache[n] for n in sorted(cache) if 8185 <= cache[n] <= 8200})
for n in sorted(cache):
    if cache[n] in (8192, 8193):
        hits[cache[n]] = n
for r, n in sorted(hits.items()):
    expect_rows(f"boundary rows={r} n={n}", family(n))

summary()
EOF
